    cabecera = len(bloques["__cabecera__"])
    ultimo = None
    for i in range(len(salida) - 1, cabecera - 1, -1):
        if salida[i].startswith("### `"):
            ultimo = i
            break
    if ultimo is not None:
        del salida[ultimo:]
        recortado = True
    else:
        if len(salida) <= cabecera:
            break
        salida.pop()
        recortado = True
if recortado:
